<script setup lang="ts">import { ref } from 'vue';import { ElButton,ElForm,ElFormItem,ElInputNumber,ElMessage,ElOption,ElSelect,ElSwitch,ElTabPane,ElTabs } from 'element-plus';import { useDemoServiceStore } from '#/features/service/demo-store';const store=useDemoServiceStore(),tab=ref('session');function save(){if(store.reception.firstResponseMinutes<1||store.reception.inactiveCloseMinutes<1)return ElMessage.error('时间必须为正整数。');ElMessage.success('设置已保存')}</script>
<template><main class="settings-page"><header><h1>聊天与接待</h1></header><section><ElTabs v-model="tab"><ElTabPane name="session" label="会话设置"><ElForm label-position="top"><ElFormItem label="首次人工回复超时转接（分钟）" required><ElInputNumber v-model="store.reception.firstResponseMinutes" :min="1" :precision="0"/></ElFormItem><ElFormItem label="无消息自动结束（分钟）" required><ElInputNumber v-model="store.reception.inactiveCloseMinutes" :min="1" :precision="0"/></ElFormItem></ElForm></ElTabPane><ElTabPane name="notification" label="消息通知"><div class="setting-row"><span><b>标签页标题闪烁</b><small>收到新客户消息时提示</small></span><ElSwitch v-model="store.reception.titleBlink"/></div><div class="setting-row"><span><b>浏览器通知</b><small>需要浏览器授予通知权限</small></span><ElSwitch v-model="store.reception.browserNotification"/></div><div class="setting-row"><span><b>消息提示音</b><small>短时间连续消息合并播放</small></span><ElSwitch v-model="store.reception.sound"/></div></ElTabPane><ElTabPane name="tools" label="聊天工具"><div class="setting-row"><span><b>接收消息自动翻译</b><small>仅支持文本消息</small></span><ElSwitch v-model="store.reception.receiveTranslation"/></div><div class="setting-row"><span><b>发送前翻译预览</b><small>使用译文后才替换输入内容</small></span><ElSwitch v-model="store.reception.sendTranslation"/></div><ElForm label-position="top"><ElFormItem label="工作语言"><ElSelect v-model="store.reception.workLanguage"><ElOption label="简体中文" value="简体中文"/><ElOption label="英语" value="英语"/></ElSelect></ElFormItem><ElFormItem label="访客语言"><ElSelect v-model="store.reception.visitorLanguage"><ElOption label="英语" value="英语"/><ElOption label="简体中文" value="简体中文"/></ElSelect></ElFormItem></ElForm></ElTabPane></ElTabs><footer><ElButton type="primary" @click="save">保存设置</ElButton></footer></section></main></template>
